import gurobipy as gp
from gurobipy import GRB
capacity_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
platforms = []
capacities = {}
for rec in capacity_records:
    pid = rec['values']['PlatformID']
    platforms.append(pid)
    capacities[pid] = int(rec['values']['Capacity'])
products = []
values = {}
weights = {}
for rec in product_records:
    pname = rec['values']['ProductName']
    products.append(pname)
    values[pname] = int(rec['values']['Value'])
    weights[pname] = int(rec['values']['Weight'])
if len(platforms) == 0 or len(products) == 0:
    raise ValueError('Missing platforms or products data.')
if set(capacities.keys()) != set(platforms):
    raise ValueError('Platform capacity data incomplete.')
if set(values.keys()) != set(products) or set(weights.keys()) != set(products):
    raise ValueError('Product value/weight data incomplete.')
m = gp.Model('VideoGameStore_Allocation')
x_vars = m.addVars(platforms, products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((values[j] * x_vars[i, j] for i in platforms for j in products)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((weights[j] * x_vars[i, j] for j in products)) <= capacities[i] for i in platforms), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')
